import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"🏆 Victoire","description":"","frontmatter":{},"headers":[],"relativePath":"regles/09-victoire.md","filePath":"regles/09-victoire.md"}'),o={name:"regles/09-victoire.md"};function r(s,e,l,u,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="🏆-victoire" tabindex="-1">🏆 Victoire <a class="header-anchor" href="#🏆-victoire" aria-label="Permalink to &quot;🏆 Victoire&quot;">​</a></h1><h2 id="conditions-de-victoire" tabindex="-1">Conditions de victoire <a class="header-anchor" href="#conditions-de-victoire" aria-label="Permalink to &quot;Conditions de victoire&quot;">​</a></h2><p>La partie se termine dès que l&#39;un des camps est <strong>entièrement éliminé</strong>.</p><h3 id="🟦-victoire-des-vivants" tabindex="-1">🟦 Victoire des Vivants <a class="header-anchor" href="#🟦-victoire-des-vivants" aria-label="Permalink to &quot;🟦 Victoire des Vivants&quot;">​</a></h3><p><strong>Condition</strong> : tous les Revenants sont K.O. (masques brisés).</p><p>Quand le dernier Revenant tombe :</p><ol><li>Le bot annonce la victoire dans le salon général.</li><li>La partie est terminée.</li><li>La composition complète est révélée.</li></ol><h3 id="🟥-victoire-des-revenants" tabindex="-1">🟥 Victoire des Revenants <a class="header-anchor" href="#🟥-victoire-des-revenants" aria-label="Permalink to &quot;🟥 Victoire des Revenants&quot;">​</a></h3><p><strong>Condition</strong> : tous les Vivants sont K.O. (masques brisés).</p><p>Quand le dernier Vivant tombe :</p><ol><li>Le bot annonce la victoire dans le salon général.</li><li>La partie est terminée.</li><li>La composition complète est révélée.</li></ol><h2 id="revelation-finale" tabindex="-1">Révélation finale <a class="header-anchor" href="#revelation-finale" aria-label="Permalink to &quot;Révélation finale&quot;">​</a></h2><p>Après la victoire, le bot révèle :</p><ul><li>Le <strong>camp gagnant</strong>.</li><li>La <strong>composition complète</strong> de la partie : <ul><li>Chaque joueur et son masque.</li><li>Chaque joueur et son camp (Vivant ou Revenant).</li><li>Le nombre de Revenants et de Vivants.</li></ul></li></ul><blockquote><p><strong>Important</strong> : la composition réelle n&#39;est révélée qu&#39;à ce moment. Personne ne peut prouver qui était Revenant avant la fin.</p></blockquote><h2 id="fin-anticipee" tabindex="-1">Fin anticipée <a class="header-anchor" href="#fin-anticipee" aria-label="Permalink to &quot;Fin anticipée&quot;">​</a></h2><h3 id="tous-les-joueurs-k-o" tabindex="-1">Tous les joueurs K.O. <a class="header-anchor" href="#tous-les-joueurs-k-o" aria-label="Permalink to &quot;Tous les joueurs K.O.&quot;">​</a></h3><p>Si tous les joueurs sont K.O. (masques brisés), la partie se termine sans vainqueur. C&#39;est un match nul.</p><h3 id="abandon" tabindex="-1">Abandon <a class="header-anchor" href="#abandon" aria-label="Permalink to &quot;Abandon&quot;">​</a></h3><p>Si un joueur quitte la partie avant la fin :</p><ul><li>Son masque est considéré comme <strong>brisé</strong> (son identité est révélée).</li><li>Son camp reste secret.</li><li>La partie continue.</li></ul><h3 id="annulation-par-l-hote" tabindex="-1">Annulation par l&#39;Hôte <a class="header-anchor" href="#annulation-par-l-hote" aria-label="Permalink to &quot;Annulation par l&#39;Hôte&quot;">​</a></h3><p>L&#39;Hôte du Carnaval peut annuler la partie à tout moment via la commande <code>/carnival-annuler-partie</code>. La composition est révélée.</p><h2 id="statistiques-de-fin" tabindex="-1">Statistiques de fin <a class="header-anchor" href="#statistiques-de-fin" aria-label="Permalink to &quot;Statistiques de fin&quot;">​</a></h2><p>Après la victoire, le bot affiche :</p><ul><li>Le <strong>nombre total de nuits</strong>.</li><li>Le <strong>nombre de Duels</strong>.</li><li>Le <strong>nombre de masques brisés</strong>.</li><li>Le <strong>camp gagnant</strong>.</li><li>La <strong>composition complète</strong>.</li></ul>',26)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
